/**
 * Real Image Intelligence Engine — Visual Intelligence v1.1.0
 *
 * Provides genuine, high-resolution, CC-licensed and verified photography
 * for websites generated by Achu Coding Agent.
 *
 * Primary Provider: Wikimedia Commons REST API (free, fast, legal, 80M+ CC media)
 * Secondary Provider: Curated high-resolution Unsplash photography fallback library
 * Download Engine: Validates image headers, magic bytes, and persists to workspace
 */

import fs from "node:fs";
import path from "node:path";

// ---------------------------------------------------------------------------
// Types
// ---------------------------------------------------------------------------

export interface ImageSearchResult {
  id: string;
  title: string;
  url: string;
  thumbnailUrl: string;
  source: "wikimedia" | "unsplash" | "curated";
  license?: string;
  creator?: string;
  attribution?: string;
  width?: number;
  height?: number;
  altText: string;
}

export interface ImageRequirement {
  slot: "hero" | "gallery" | "feature" | "showcase" | "detail" | "profile" | "background";
  description: string;
  query: string;
  aspectRatio: "16:9" | "4:3" | "1:1" | "21:9" | "3:4";
}

